'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `prototype` property', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'prototype' ), true, 'has property' );
	t.end();
});

tape( 'the property value is a non-null object', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( typeof f.prototype, 'object', 'returns expected value' );
	t.notEqual( f.prototype, null, 'is not null' );
	t.end();
});

tape( 'the `prototype.constructor` property refers back to the function', function test( t ) {
	var f;

	f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( f.prototype.constructor, f, 'refers to the function' );
	t.end();
});

tape( 'each function instance has its own distinct `prototype` object', function test( t ) {
	var f;
	var g;

	f = new Fcn( 'return 1' );
	g = new Fcn( 'return 2' );
	t.notEqual( f.prototype, g.prototype, 'prototypes are distinct objects' );
	t.end();
});
